/**
 * The photograph to show a customer for this application, or null.
 *
 * Technology has to match, and one of the substrate words has to appear in what the
 * rep typed. No fuzzy matching and no fallback to a generic shot: a photograph of a
 * bottling line on a quote for corrugated cases would be worse than no photograph,
 * because the customer would reasonably read it as a statement about their line.
 *
 * Whole words only. A plain `includes` matched PET inside "PETG clamshell" and put a
 * photograph of glass bottles on a thermoformed-tray quote — the same substring trap
 * that made "pet food" parse as a PET bottle, in a second place.
 */
export function applicationPhotoFor(
  technologyCode: string | null | undefined,
  substrate: string | null | undefined,
): ApplicationPhoto | null {
  if (!technologyCode || !substrate) return null;
  const said = substrate.toLowerCase();
  // No escaping: this script refuses to emit a substrate word that is not plain
  // letters and spaces, so there is nothing here for a metacharacter to do.
  const names = (word: string) =>
    new RegExp(`(?:^|[^a-z])${word}(?![a-z])`).test(said);
  return APPLICATION_PHOTOS.find((p) => p.technology === technologyCode
    && p.substrate.some(names)) ?? null;
}
